<template><div class="mx-auto max-w-md py-6 sm:py-12"><AppCard><h1 class="text-2xl font-bold text-slate-900">ورود به یار تو</h1><p class="mt-2 text-sm text-slate-500">به برنامه‌های روزمره‌ات برگرد.</p><form class="mt-6 space-y-4" @submit.prevent="submit"><label class="block text-sm font-medium">ایمیل<input v-model="form.email" type="email" autocomplete="email" required class="focus-ring mt-2 w-full rounded-xl border border-slate-300 px-4" dir="ltr"></label><label class="block text-sm font-medium">رمز عبور<input v-model="form.password" type="password" autocomplete="current-password" required class="focus-ring mt-2 w-full rounded-xl border border-slate-300 px-4" dir="ltr"></label><p v-if="error" class="rounded-lg bg-red-50 p-3 text-sm text-red-700" role="alert">{{ error }}</p><button class="focus-ring w-full rounded-xl bg-teal-700 px-4 py-3 font-bold text-white disabled:opacity-60" :disabled="loading">{{ loading ? 'در حال ورود…' : 'ورود' }}</button></form><p class="mt-5 text-center text-sm text-slate-600">حساب ندارید؟ <NuxtLink to="/register" class="font-bold text-teal-700">ثبت‌نام کنید</NuxtLink></p></AppCard></div></template>
<script setup lang="ts">
const { fetch: fetchSession } = useUserSession()
const form = reactive({ email: '', password: '' }); const error = ref(''); const loading = ref(false)
async function submit() { loading.value = true; error.value = ''; try { await $fetch('/api/auth/login', { method: 'POST', body: form }); await fetchSession(); await navigateTo('/dashboard') } catch (e: any) { error.value = e?.data?.message || e?.statusMessage || 'ورود انجام نشد. دوباره تلاش کنید.' } finally { loading.value = false } }
</script>
